      expect(range.count).toBe(0);
      expect(range.showing).toBe("there is no comment 10; this issue has 4");
      expect(range.showing).not.toContain("read the rest");
    });

    test("from after to", () => {
      const range = selectCommentRange(20, 9, 3);
      expect(range.count).toBe(0);
