  // The four interacting defaults live in `domain/work/comment-range.ts`, where the
  // truth table is testable without a `gh` in the loop.
  const range = selectCommentRange(all.length, a.from, a.to);

  // A continuation names ONE comment, because the offset has no meaning across
  // several. Refused rather than silently applied to the first of them: a caller
  // that passed the range it was already reading would otherwise get comment 2's
  // opening cut at an offset taken from comment 1, and no sign that it happened.
  if (a.body_offset !== undefined && range.count !== 1) {
    mcpFail(
      "`body_offset` continues ONE comment, so the range has to name exactly one: " +
        (range.count === 0 ? `${range.showing}.` : `this read selects comment(s) ${range.from}-${range.to} of ${all.length}.`) +
        " Pass `from` naming the comment whose cut marker gave the offset.",
    );
  }

  // The budget is divided among the comments this read selects, so a read of one
  // comment gets all of it. `PER_ITEM_BUDGET`'s fixed fifth was what cut #149's
  // comments at 1,600 characters while the tail -- the decision -- was the part
  // that never arrived.
  const perCommentBudget = Math.max(
    MIN_COMMENT_BUDGET,
    Math.floor(TOOL_OUTPUT_BUDGET / Math.max(1, range.count)),
  );

  const selected = (range.count > 0 ? all.slice(range.from - 1, range.to) : []).map((comment) => {
    const body = (comment as { body?: unknown }).body;
    if (typeof body !== "string") return comment;
    const index = (comment as { index: number }).index;
    // Only a one-comment range can carry an offset, so the other comment in a
    // range never arrives here mid-body.
    const offset = range.count === 1 ? (a.body_offset ?? 0) : 0;
    if (offset > 0 && offset >= body.length) {
      mcpFail(
        `Comment ${index} is ${body.length} characters long; \`body_offset\` ${offset} is past its end. ` +
          "Pass the offset a cut marker named, or omit it to read from the beginning.",
      );
    }
    return { ...comment, body: readCommentBody(body, { index, budget: perCommentBudget, offset }).text };
  });
  ...
```

